<?php
require_once __DIR__ . '/functions.php';
function secure_session(): void { if(session_status()===PHP_SESSION_NONE){session_name(SESSION_NAME);session_set_cookie_params(['httponly'=>true,'secure'=>(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'),'samesite'=>'Lax','path'=>'/']);session_start();} }
function is_public_ip(string $host): bool { if(filter_var($host,FILTER_VALIDATE_IP)){return filter_var($host,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)!==false;} if(!preg_match('/^[a-z0-9.-]+$/i',$host))return false; $ips=gethostbynamel($host)?:[];return count($ips)>0 && !array_filter($ips,fn($ip)=>!filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)); }
function validate_image_file(string $path): array { $f=new finfo(FILEINFO_MIME_TYPE);$mime=$f->file($path);$ext=mime_extension($mime);if(!$ext)throw new RuntimeException('Only JPG, PNG, WEBP and GIF images are allowed.');$info=@getimagesize($path);if(!$info)throw new RuntimeException('Invalid image data.');if($info[0]*$info[1]>MAX_IMAGE_PIXELS)throw new RuntimeException('Image dimensions are too large.');return [$mime,$ext,(int)$info[0],(int)$info[1]]; }
